::view-transition-old(.page-change) {
    animation: .15s cubic-bezier(.4, 0, 1, 1) both page-change-out
}

::view-transition-new(.page-change) {
    animation: .22s cubic-bezier(.215, .61, .355, 1) both page-change-in
}

::view-transition {
    pointer-events: none
}

@keyframes page-change-out {
    to {
        opacity: 0;
        translate: 0 -4px
    }
}

@keyframes page-change-in {
    0% {
        opacity: 0;
        translate: 0 6px
    }
}

@media (prefers-reduced-motion:reduce) {
    ::view-transition-old(*) {
        animation-duration: 0s !important;
        animation-delay: 0s !important
    }

    ::view-transition-new(*) {
        animation-duration: 0s !important;
        animation-delay: 0s !important
    }

    ::view-transition-group(*) {
        animation-duration: 0s !important;
        animation-delay: 0s !important
    }
}

