    opacity: 0
}

.gardenScene[data-animate=true][data-ready=true] .groomCharacter {
    animation: 1.8s cubic-bezier(.22, .61, .36, 1) .12s both groomArrival
}

.gardenScene[data-animate=true][data-ready=true] .brideCharacter {
    animation: 1.8s cubic-bezier(.22, .61, .36, 1) .25s both brideArrival
}

.gardenScene[data-animate=true][data-ready=true] .character img {
    animation: .45s ease-in-out .12s 4 walkingSway
}

.gardenScene[data-animate=true][data-ready=true] .brideCharacter img {
    animation-delay: .25s
}

.gardenScene[data-animate=true][data-ready=true] .sceneMotes {
    animation: 1.4s 1.5s both gardenShimmer
}

@keyframes groomArrival {
    0% {
        opacity: 0;
        transform: translate(-78%)
    }

    18% {
        opacity: 1
    }

    to {
        opacity: 1;
        transform: translate(0)
    }
}

@keyframes brideArrival {
    0% {
        opacity: 0;
        transform: translate(85%)
    }

    18% {
        opacity: 1
    }

    to {
        opacity: 1;
        transform: translate(0)
    }
}

@keyframes walkingSway {

    0%,
    to {
        transform: translateY(0)rotate(0)
    }

    50% {
        transform: translateY(-3px)rotate(.6deg)
    }
}

@keyframes gardenShimmer {
    0% {
        opacity: 0;
        transform: translateY(9px)
    }

    to {
        opacity: 1;
        transform: translateY(0)
    }
}

