.folding-module___fOx4G__scene {
    --paper: #f9f7ef;
    --ink: #34493b;
    min-height: calc(100 * var(--editor-vh, 1dvh));
    isolation: isolate;
    color: var(--ink);
    background: #dfe7df;
    place-items: center;
    padding: 90px 16px 70px;
    font-family: Lora, Georgia, serif;
    display: grid;
    position: relative;
    overflow: clip
}

.folding-module___fOx4G__paperSpread {
    z-index: -1;
    background: var(--paper);
    transform: scale(var(--spread-start-x, .32), var(--spread-start-y, .6));
    position: absolute;
    inset: 0
}

.folding-module___fOx4G__spread {
    transform: none
}

.folding-module___fOx4G__scene[data-fold-state=opening] .folding-module___fOx4G__spread {
    animation: .9s cubic-bezier(.22, .7, .2, 1) 2.05s both folding-module___fOx4G__extend-paper
}

.folding-module___fOx4G__scene[data-fold-state=opening] :is(.folding-module___fOx4G__spread, .folding-module___fOx4G__wing, .folding-module___fOx4G__seal) {
    will-change: transform
}

.folding-module___fOx4G__book {
    width: min(calc(86 * var(--editor-vw, 1vw)), 360px);
    height: min(calc(70 * var(--editor-vh, 1svh)), 520px);
    perspective: 1800px;
    min-height: 320px;
    position: relative
}

.folding-module___fOx4G__leaf {
    text-align: center;
    background: var(--paper);
    border: 1px solid #d7d7c6;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    padding: 52px 30px 30px;
    display: flex;
    position: absolute;
    inset: 0
}

.folding-module___fOx4G__scene[data-fold-state=opening] .folding-module___fOx4G__leaf,
.folding-module___fOx4G__scene[data-fold-state=open] .folding-module___fOx4G__leaf {
    color: #f8f4e9;
    background: #31483b;
    border-color: #aebca2;
    box-shadow: 0 18px 50px #263d3040
}

.folding-module___fOx4G__scene[data-fold-state=opening] .folding-module___fOx4G__leaf:after,
.folding-module___fOx4G__scene[data-fold-state=open] .folding-module___fOx4G__leaf:after {
    border-color: #b6c3aa66
}

.folding-module___fOx4G__leaf:after {
    content: "";
    pointer-events: none;
    border: 1px solid #dbddcd;
    position: absolute;
    inset: 12px
}

.folding-module___fOx4G__leaf>* {
    flex-shrink: 0
}

.folding-module___fOx4G__innerFlower {
    object-fit: contain;
    opacity: .4;
    pointer-events: none;
    width: 100px;
    height: 130px;
    position: absolute;
    top: 20px;
    right: 18px
}

.folding-module___fOx4G__kicker {
    letter-spacing: .22em;
    margin: 0 0 24px;
    font-size: 10px;
    position: relative
}

.folding-module___fOx4G__names {
    font: 500 clamp(32px, calc(8.5 * var(--editor-vw, 1vw)), 48px)/1.07 "Cormorant Garamond", Georgia, serif;
    text-shadow: 0 2px 18px #172b2040;
    outline: none;
    width: 100%;
    margin: 0;
    position: relative
}

.folding-module___fOx4G__names>span,
.folding-module___fOx4G__names>span>span {
    display: block
}

.folding-module___fOx4G__names i {
    color: #c1cdb4;
    padding: 6px 0;
    font: 34px/1 The Nautigal, cursive;
    display: block
}

.folding-module___fOx4G__date {
    letter-spacing: .12em;
    margin: 25px 0 0;
    font: 20px/1.4 Cormorant Garamond, Georgia, serif;
    position: relative
}

.folding-module___fOx4G__date span {
    color: #b9c8af;
    margin: 0 10px
}

.folding-module___fOx4G__note {
    color: #e8e4d8;
    max-width: 240px;
    margin: 18px 0 0;
    font-size: 12px;
    line-height: 1.8;
    position: relative
}

.folding-module___fOx4G__innerGuest {
    overflow-wrap: anywhere;
    max-width: 100%;
    margin: 10px 0 0;
    font-size: 12px;
    line-height: 1.6;
    position: relative
}

.folding-module___fOx4G__wing {
    width: 50.15%;
    height: 100%;
    transform-style: preserve-3d;
    z-index: 2;
    position: absolute;
    top: 0
}

.folding-module___fOx4G__leftWing {
    transform-origin: 0;
    left: 0
}

.folding-module___fOx4G__rightWing {
    transform-origin: 100%;
    z-index: 1;
    right: 0
}

.folding-module___fOx4G__front,
.folding-module___fOx4G__back {
    backface-visibility: hidden;
    background: var(--paper);
    border: 1px solid #d1d2bf;
    position: absolute;
    inset: 0
}

.folding-module___fOx4G__front {
    background-image: url(assets/ivory-blind-emboss-paper-480.webp);
    background-size: 360px 540px;
    flex-direction: column;
    align-items: center;
    padding: 40px 16px;
    display: flex;
    overflow: hidden;
    transform: translateZ(.2px)
}

.folding-module___fOx4G__leftWing .folding-module___fOx4G__front {
    border-right-color: #b7bca8;
    box-shadow: -9px 14px 24px #34493b12
}

.folding-module___fOx4G__rightWing .folding-module___fOx4G__front {
    background-position: 100% 0;
    box-shadow: 9px 14px 24px #34493b12
}

.folding-module___fOx4G__coverWord {
    margin-bottom: 28px;
    font: 38px/1.2 The Nautigal, cursive
}

.folding-module___fOx4G__coverName {
    z-index: 1;
    font: 500 clamp(24px, calc(6.3 * var(--editor-vw, 1vw)), 31px)/1.15 "Cormorant Garamond", Georgia, serif;
    text-align: center;
    text-wrap: balance;
    overflow-wrap: anywhere;
    position: relative
}

.folding-module___fOx4G__coverName[data-long-name=true] {
    font-size: clamp(18px, calc(5.2 * var(--editor-vw, 1vw)), 25px)
}

.folding-module___fOx4G__coverFlower {
    object-fit: contain;
    pointer-events: none;
    width: 210px;
    max-width: none;
    height: 240px;
    position: absolute;
    bottom: -26px;
    left: -35px
}

.folding-module___fOx4G__rightWing .folding-module___fOx4G__coverFlower {
    width: 190px;
    height: 270px;
    bottom: -24px;
    left: 0;
    transform: rotate(-18deg)
}

.folding-module___fOx4G__back {
    background: linear-gradient(90deg, #edeedf, var(--paper) 18%, #f9f7ef);
    transform: rotateY(180deg)translateZ(.2px)
}

.folding-module___fOx4G__backFlower {
    object-fit: contain;
    opacity: .5;
    width: 160px;
    height: 220px;
    position: absolute;
    bottom: 0;
    left: 0
}

.folding-module___fOx4G__rightWing .folding-module___fOx4G__back {
    background: linear-gradient(270deg, #edeedf, var(--paper) 18%, #f9f7ef)
}

.folding-module___fOx4G__rightWing .folding-module___fOx4G__backFlower {
    left: auto;
    right: 0;
    transform: scaleX(-1)
}

.folding-module___fOx4G__seal {
    z-index: 4;
    width: 98px;
    color: var(--ink);
    text-align: center;
    cursor: pointer;
    backface-visibility: hidden;
    text-decoration: none;
    position: absolute;
    top: 48%;
    right: -49px;
    transform: translateZ(3px)
}

.folding-module___fOx4G__seal img {
    object-fit: contain;
    filter: drop-shadow(0 4px 3px #34493b30);
    width: 98px;
    height: 98px;
    transition: transform .25s;
    display: block
}

.folding-module___fOx4G__seal span {
    background: var(--ink);
    color: #fff;
    white-space: nowrap;
    letter-spacing: .04em;
    margin-top: 10px;
    padding: 9px 15px;
    font-size: 12px;
    display: inline-block
}

.folding-module___fOx4G__seal:hover img {
    transform: translateY(-4px)rotate(-6deg)
}

.folding-module___fOx4G__seal:focus-visible {
    outline: 2px solid var(--ink);
    outline-offset: -2px
}

.folding-module___fOx4G__seal[aria-disabled=true] {
    cursor: default;
    pointer-events: none
}

.folding-module___fOx4G__address {
    top: max(20px, calc(50% - min(calc(35 * var(--editor-vh, 1svh)), 260px) - 66px));
    text-align: center;
    transition: opacity .35s, transform .5s;
    position: absolute;
    left: 22px;
    right: 22px
}

.folding-module___fOx4G__address p {
    letter-spacing: .1em;
    margin: 0;
    font-size: 11px
}

.folding-module___fOx4G__address .folding-module___fOx4G__guest {
    letter-spacing: 0;
    overflow-wrap: anywhere;
    max-width: 420px;
    margin: 7px auto 0;
    font-size: 13px;
    line-height: 1.6
}

.folding-module___fOx4G__caption {
    bottom: max(24px, calc(50% - min(calc(35 * var(--editor-vh, 1svh)), 260px) - 50px));
    text-align: center;
    margin: 0;
    font: 23px/1.3 The Nautigal, cursive;
    transition: opacity .4s;
    position: absolute
}

.folding-module___fOx4G__scene[data-fold-state=opening] .folding-module___fOx4G__address,
.folding-module___fOx4G__scene[data-fold-state=open] .folding-module___fOx4G__address {
    opacity: 0;
    pointer-events: none;
    transform: translateY(-10px)
}

.folding-module___fOx4G__scene[data-fold-state=opening] .folding-module___fOx4G__caption,
.folding-module___fOx4G__scene[data-fold-state=open] .folding-module___fOx4G__caption {
    opacity: 0
}

.folding-module___fOx4G__unfolded .folding-module___fOx4G__leftWing {
    transform: rotateY(-180deg)
}

.folding-module___fOx4G__scene[data-fold-state=opening] .folding-module___fOx4G__leftWing {
    animation: 2.4s cubic-bezier(.32, .05, .18, 1) .35s both folding-module___fOx4G__left-unfold
}

.folding-module___fOx4G__unfolded .folding-module___fOx4G__rightWing {
    transform: rotateY(180deg)
}

.folding-module___fOx4G__scene[data-fold-state=opening] .folding-module___fOx4G__rightWing {
    animation: 2.38s cubic-bezier(.32, .05, .18, 1) .48s both folding-module___fOx4G__right-unfold
}

.folding-module___fOx4G__scene[data-fold-state=opening] .folding-module___fOx4G__seal {
    animation: .65s cubic-bezier(.25, .6, .25, 1) both folding-module___fOx4G__peel-seal
}

.folding-module___fOx4G__scene[data-fold-state=open] .folding-module___fOx4G__wing {
    pointer-events: none
}

.folding-module___fOx4G__scene[data-fold-state=open] .folding-module___fOx4G__seal {
    visibility: hidden
}

.folding-module___fOx4G__status {
    clip-path: inset(50%);
    width: 1px;
    height: 1px;
    position: absolute;
    overflow: hidden
}

@keyframes folding-module___fOx4G__peel-seal {
    0% {
        transform: translateZ(3px)
    }

    to {
        transform: translate(-32px, -24px)translateZ(36px)rotate(-22deg)rotateY(-30deg)
    }
}

@keyframes folding-module___fOx4G__left-unfold {
    0% {
        transform: rotateY(0)
    }

    to {
        transform: rotateY(-180deg)
    }
}

@keyframes folding-module___fOx4G__right-unfold {
    0% {
        transform: rotateY(0)
    }

    to {
        transform: rotateY(180deg)
    }
}

@keyframes folding-module___fOx4G__extend-paper {
    0% {
        transform: scale(var(--spread-start-x, .32), var(--spread-start-y, .6))
    }

    to {
        transform: scale(1)
    }
}

@media (max-height:650px) {
    .folding-module___fOx4G__scene {
